    ? `<span class="job-card-elapsed" data-started="${_esc(startedAt)}" data-run-id="${_esc(run.latest_run_id || run.run_id)}">0s</span>`
    : '';
  const turnHtml = isRunning && progress.turn ? `<span class="job-card-turn"> · T:${progress.turn}</span>` : '';
  const statusLineHtml = isRunning && progress.snippet
    ? `<div class="job-card-status-line">${_esc(progress.snippet)}</div>` : '';
  const attemptHtml = attempt > 0 ? `<span class="job-card-attempt">↺${attempt}</span> ` : '';
  const tokensHtml = (run.input_tokens || run.output_tokens)
    ? `<span style="font-size:10px;color:var(--text-dim)">${_fmt((run.input_tokens||0)+(run.output_tokens||0))} tok</span>` : '';
  const modelLabel = run.model || run.agent || '';
  const modelBadge = modelLabel ? ` <span class="model-badge">${_esc(modelLabel)}</span>` : '';
  const pa = run.preferred_agent || '';
  const paLabel = pa === 'claude' ? 'CLAUDE' : pa === 'codex' ? 'CODEX' : '·';
  const paClass = pa || 'none';
  const agentLocked = isRunning || state === 'in_progress';
