function _pacePct(resets_at_unix, window_minutes) {
  if (!resets_at_unix || !window_minutes) return null;
  const nowSec = Date.now() / 1000;
  const windowSec = window_minutes * 60;
  const startSec = resets_at_unix - windowSec;
  const elapsed = nowSec - startSec;
  return Math.max(0, Math.min(100, elapsed / windowSec * 100));
}

function _applyPaceMarker(marker, elapsedPct, usedPct) {
  if (elapsedPct === null) { marker.style.display = 'none'; return; }
  marker.style.display = '';
  marker.style.left = elapsedPct.toFixed(1) + '%';
  const delta = usedPct - elapsedPct;
  if (Math.abs(delta) < 5) marker.className = 'win-pace-marker on-pace';
  else if (delta > 0) marker.className = 'win-pace-marker behind';
  else marker.className = 'win-pace-marker ahead';
}

