<script>
// ── xterm.js + PTY via Socket.IO ────────────────────────────────────────────
const term = new Terminal({
  theme: {
    background: '#0d0d0d', foreground: '#d4d4d4',
    cursor: '#e8723a', selectionBackground: 'rgba(232,114,58,0.25)',
  },
  fontFamily: "'SF Mono', 'Fira Code', 'Fira Mono', 'Cascadia Code', monospace",
  fontSize: 13, lineHeight: 1.0,
  cursorBlink: true, cursorStyle: 'block',
  scrollback: 2000,
});
const fitAddon = new FitAddon.FitAddon();
term.loadAddon(fitAddon);
const terminalEl = document.getElementById('terminal');
const terminalResizeHandle = document.getElementById('term-resize-handle');
const DEFAULT_TERM_HEIGHT = 300;
const MIN_TERM_HEIGHT = 200;
const MAX_TERM_HEIGHT = Math.floor(window.innerHeight * 0.75);

function clampTerminalHeight(h) { return Math.max(MIN_TERM_HEIGHT, Math.min(MAX_TERM_HEIGHT, h)); }
function applyTerminalHeight(h) { terminalEl.style.height = `${clampTerminalHeight(h)}px`; fitAddon.fit(); }
function loadTerminalHeight() {
  const saved = Number(window.localStorage.getItem('agenticos.terminal.height'));
  return Number.isFinite(saved) && saved > 0 ? saved : DEFAULT_TERM_HEIGHT;
}

term.open(terminalEl);
applyTerminalHeight(loadTerminalHeight());

const socket = io();

socket.on('connect', () => {
  fitAddon.fit();
  const { cols, rows } = term;
  socket.emit('pty_start', { cols, rows });
});

socket.on('pty_output', (data) => { term.write(data.data); });

socket.on('run_logged', () => { refreshJobBoard(); });

socket.on('run_state_change', (data) => {
  if (data.run_id && data.state) {
    updateJobCardState(data.run_id, data.state);
  }
});

term.onData((data) => { socket.emit('pty_input', { data }); });
term.onResize(({ cols, rows }) => { socket.emit('pty_resize', { cols, rows }); });
window.addEventListener('resize', () => {
  const h = terminalEl.getBoundingClientRect().height;
  terminalEl.style.height = `${clampTerminalHeight(h)}px`;
  fitAddon.fit();
});

let terminalResizeState = null;
function stopTerminalResize() {
  if (!terminalResizeState) return;
  window.localStorage.setItem('agenticos.terminal.height', String(Math.round(terminalEl.getBoundingClientRect().height)));
  terminalResizeState = null;
  document.body.style.userSelect = '';
}
function resizeTerminalFromPointer(clientY) {
  if (!terminalResizeState) return;
  applyTerminalHeight(terminalResizeState.startHeight + (clientY - terminalResizeState.startY));
}
terminalResizeHandle.addEventListener('mousedown', (e) => {
  terminalResizeState = { startY: e.clientY, startHeight: terminalEl.getBoundingClientRect().height };
  document.body.style.userSelect = 'none';
  e.preventDefault();
});
window.addEventListener('mousemove', (e) => resizeTerminalFromPointer(e.clientY));
window.addEventListener('mouseup', () => stopTerminalResize());

function injectCommand(phrase) {
  socket.emit('pty_input', { data: phrase });
  term.focus();
}
function clearTerm() {
  socket.emit('pty_input', { data: 'clear\n' });
  term.focus();
}
function commandForSkill(name) {
  return selectedAgent === 'codex' ? `$${name} ` : `/${name} `;
}
function selectSkill(event, name, phrase) {
  setSelectedSkill(name);
  const command = (event && (event.altKey || event.shiftKey)) ? phrase : commandForSkill(name);
  socket.emit('skill_selected', { skill: name, phrase: command });
  injectCommand(command);
}
function clearPrompt() { clearTerm(); }

// Drag-and-drop file → inject server path into PTY
terminalEl.addEventListener('dragover', (e) => {
  e.preventDefault();
  e.dataTransfer.dropEffect = 'copy';
  terminalEl.style.outline = '2px dashed var(--accent)';
});
terminalEl.addEventListener('dragleave', () => { terminalEl.style.outline = ''; });
terminalEl.addEventListener('drop', async (e) => {
  e.preventDefault();
  terminalEl.style.outline = '';
  for (const file of Array.from(e.dataTransfer.files)) {
    const fd = new FormData();
    fd.append('file', file);
    try {
      const res = await fetch('/upload', { method: 'POST', body: fd });
      const data = await res.json();
      if (data.path) { socket.emit('pty_input', { data: data.path }); term.focus(); }
      else { term.write(`\r\n[upload error: ${data.error}]\r\n`); }
    } catch (err) { term.write(`\r\n[upload error: ${err}]\r\n`); }
  }
});
</script>
