// ── Job Board — kanban columns ──────────────────────────────────────────────

let _detailRunId = null;

const JOB_COLS = [
  { key: 'backlog', label: 'Backlog',      states: ['backlog', 'sent'],           dotClass: 'backlog', droppable: false },
  { key: 'todo',    label: 'Todo',         states: ['todo'],                       dotClass: 'todo',    droppable: true, dropStatus: 'todo'   },
  { key: 'in_progress', label: 'In Progress',  states: ['in_progress'],                dotClass: 'running', droppable: false },
  { key: 'in_review',  label: 'In review', states: ['in_review'],                    dotClass: 'review',  droppable: false },
  { key: 'done',    label: 'Done',         states: ['done'],                       dotClass: 'done',    droppable: false },
  { key: 'cancelled', label: 'Canceled',   states: ['cancelled'],  dotClass: 'cancelled', droppable: true, dropStatus: 'cancelled' },
];

const HIDDEN_COLS = [];

const ALL_COLS = [...JOB_COLS, ...HIDDEN_COLS];

function _stateBadgeHtml(state) {
  const dot = state === 'running' ? '<span class="pulse-dot"></span>' : '';
  const labels = {
    running: 'Running', success: 'Done', failed: 'Failed', timeout: 'Timeout',
    sent: 'Sent', backlog: 'Backlog', error: 'Error', todo: 'Todo', rework: 'Rework',
    merging: 'Merging', cancelled: 'Canceled', duplicate: 'Duplicated',
    stalled: 'Stalled', queued: 'Queued', review: 'In review',
    in_progress: 'In Progress', in_review: 'In review', done: 'Done',
  };
  return `<span class="state-badge ${state}">${dot}${labels[state] || state}</span>`;
}

function _buildCol(col, items) {
  const isTodo = col.key === 'todo';
  const colEl = document.createElement('div');
  colEl.className = 'job-col';
  colEl.dataset.colKey = col.key;
  const addBtn = isTodo
    ? `<button type="button" class="col-add-btn" onclick="openNewIssueModal()" title="New task">+</button>`
    : '';
  colEl.innerHTML = `
    <div class="job-col-header">
      <div class="job-col-dot ${col.dotClass}"></div>
      <span class="job-col-title">${col.label}</span>
      <span class="job-col-count">${items.length}</span>
      ${addBtn}
    </div>
    <div class="job-col-body"></div>
  `;
  const body = colEl.querySelector('.job-col-body');
  if (items.length === 0) {
    body.innerHTML = '<div class="job-col-empty">No items</div>';
  } else {
    items.slice(0, _colLimit).forEach(r => body.appendChild(_buildColCard(r)));
  }
  if (col.droppable) {
    body.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
      body.style.outline = '2px solid var(--accent)';
      body.style.borderRadius = '6px';
    });
    body.addEventListener('dragleave', () => { body.style.outline = ''; });
    body.addEventListener('drop', async (e) => {
      e.preventDefault();
      body.style.outline = '';
      const run_id = e.dataTransfer.getData('text/plain');
      if (!run_id) return;
      await fetch(`/api/runs/${run_id}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: col.dropStatus }),
      });
      refreshJobBoard();
    });
  }
  return colEl;
}

let _colLimit = 15;
let _boardItemsByRunId = {};

function _shortId(run_id) {
  if (!run_id) return 'AS-?';
  if (run_id.startsWith('legacy-')) return run_id.replace('legacy-', 'AS-');
  return 'AS-' + run_id.slice(0, 6);
}

function _esc(str) {
  return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

function openLatestError() {
  if (!errorRuns.length) return;
  const latest = errorRuns.find(r => r.run_id) || errorRuns[0];
  if (latest && latest.run_id) openDetailModal(latest.run_id);
}

function _runTimeMs(run) {
  const raw = run.started_at || run.created_at || '';
  const ms = Date.parse(raw);
  return Number.isFinite(ms) ? ms : 0;
}

function _preferRun(candidate, current) {
  const candidateRunning = (candidate.status || candidate.state) === 'running';
  const currentRunning = (current.status || current.state) === 'running';
  if (candidateRunning !== currentRunning) return candidateRunning;
  const candidateAttempt = Number(candidate.attempt || 0);
  const currentAttempt = Number(current.attempt || 0);
  if (candidateAttempt !== currentAttempt) return candidateAttempt > currentAttempt;
  return _runTimeMs(candidate) >= _runTimeMs(current);
}

function _latestLinearRuns(items) {
  const unlinked = [];
  const byIssue = new Map();
  items.forEach(run => {
    const issueId = run.linear_issue_id;
    if (!issueId) {
      unlinked.push(run);
      return;
    }
    const current = byIssue.get(issueId);
    if (!current || _preferRun(run, current)) byIssue.set(issueId, run);
  });
  return unlinked.concat(Array.from(byIssue.values()));
}

// run_progress state: run_id -> {snippet, turn}
const _runProgress = {};

function _buildColCard(run) {
  const state = run._boardStatus || run.status || run.state || 'unknown';
  const card = document.createElement('div');
  card.className = 'job-card';
  card.dataset.runId = run.run_id || '';
  const prompt = (run.prompt || '').trim();
  const when = run.when || '';
  const dur = run.duration || '';
  const latestRunStatus = run.latest_run_status || run.status || '';
  const isRunning = latestRunStatus === 'running';
  const canRetry = !isRunning && !!run.latest_run_id;
  const isDraggable = false;
  const attempt = run.attempt || 0;
  const startedAt = run.started_at || '';
  const progress = _runProgress[run.latest_run_id || run.run_id] || {};

  const elapsedHtml = isRunning && startedAt
    ? `<span class="job-card-elapsed" data-started="${_esc(startedAt)}" data-run-id="${_esc(run.latest_run_id || run.run_id)}">0s</span>`
    : '';
  const turnHtml = isRunning && progress.turn ? `<span class="job-card-turn"> · T:${progress.turn}</span>` : '';
  const statusLineHtml = isRunning && progress.snippet
    ? `<div class="job-card-status-line">${_esc(progress.snippet)}</div>` : '';
  const attemptHtml = attempt > 0 ? `<span class="job-card-attempt">↺${attempt}</span> ` : '';
  const tokensHtml = (run.input_tokens || run.output_tokens)
    ? `<span style="font-size:10px;color:var(--text-dim)">${_fmt((run.input_tokens||0)+(run.output_tokens||0))} tok</span>` : '';
  const modelLabel = run.model || run.agent || '';
  const modelBadge = modelLabel ? ` <span class="model-badge">${_esc(modelLabel)}</span>` : '';
  const pa = run.preferred_agent || '';
  const paLabel = pa === 'claude' ? 'CLAUDE' : pa === 'codex' ? 'CODEX' : '·';
  const paClass = pa || 'none';
  const agentLocked = isRunning || state === 'in_progress';
  const agentBadge = run._is_linear_issue
    ? ` <span class="agent-badge ${_esc(paClass)}${agentLocked ? ' locked' : ''}" title="${agentLocked ? 'Agent locked while in progress' : 'Click to toggle agent'}" ${agentLocked ? '' : `onclick="event.stopPropagation();setIssueAgent('${_esc(run.linear_issue_id)}','${_esc(pa)}')"`}>${_esc(paLabel)}</span>`
    : '';
  const issueLabel = run.skill || run.identifier || '?';
  const issueTitle = run.title || prompt || '';

  card.innerHTML = `
    <div class="job-card-id">${attemptHtml}${_esc(issueLabel)}${modelBadge}${agentBadge}</div>
    <div class="job-card-title">${_esc(issueTitle)}</div>
    ${prompt ? `<div class="job-card-prompt">${_esc(prompt)}</div>` : ''}
    ${statusLineHtml}
    <div class="job-card-footer">
      <span>${isRunning ? elapsedHtml + turnHtml : (when ? 'Updated ' + _esc(when) : '—')}</span>
      <span class="job-card-dur">${tokensHtml || _esc(dur)}</span>
    </div>
  `;
  if (isRunning) {
    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'cancel-btn';
    cancelBtn.textContent = '✕ Cancel';
    cancelBtn.onclick = (e) => { e.stopPropagation(); cancelRun(run.run_id); };
    card.appendChild(cancelBtn);
  }
  if (run.linear_issue_id && state !== 'cancelled') {
    const dismissBtn = document.createElement('button');
    dismissBtn.className = 'job-card-dismiss';
    dismissBtn.textContent = '✕';
    dismissBtn.title = 'Cancel issue';
    dismissBtn.onclick = (e) => { e.stopPropagation(); cancelLinearIssueById(run.linear_issue_id); };
    card.appendChild(dismissBtn);
  }
  if (canRetry) {
    const group = document.createElement('div');
    group.className = 'job-btn-group';
    const btnC = document.createElement('button');
    btnC.className = 'job-btn retry-claude';
    btnC.textContent = '↺ Claude';
    btnC.title = 'Continue with Claude';
