async function refreshJobBoard() {
  try {
    const [runningRes, recentRes] = await Promise.all([
      fetch('/api/runs?state=running'),
      fetch('/api/runs?limit=40'),
    ]);
    const running = await runningRes.json();
    const recent  = await recentRes.json();

    const seen = new Set();
    const all = [];
    for (const r of running) {
      if (r.run_id && !seen.has(r.run_id)) { seen.add(r.run_id); all.push({...r, status: 'running'}); }
    }
    for (const r of recent) {
      if (r.run_id && !seen.has(r.run_id)) { seen.add(r.run_id); all.push(r); }
    }

    // Bucket by column
    const byCol = {};
    JOB_COLS.forEach(c => { byCol[c.key] = []; });
    all.forEach(r => {
      const state = r.status || r.state || 'unknown';
      const col = JOB_COLS.find(c => c.states.includes(state));
      if (col) byCol[col.key].push(r);
    });

    const container = document.getElementById('job-board-cols');
    if (!container) return;

    const runningCount = byCol['running']?.length || 0;
    document.getElementById('job-board-meta').textContent =
      runningCount > 0 ? `${runningCount} running · ${all.length} total` : `${all.length} runs`;

    const frag = document.createDocumentFragment();
    JOB_COLS.forEach(col => {
      const items = byCol[col.key] || [];
      const colEl = document.createElement('div');
      colEl.className = 'job-col';
      colEl.dataset.colKey = col.key;
      colEl.innerHTML = `
        <div class="job-col-header">
          <div class="job-col-dot ${col.dotClass}"></div>
          <span class="job-col-title">${col.label}</span>
          <span class="job-col-count">${items.length}</span>
        </div>
        <div class="job-col-body"></div>
      `;
      const body = colEl.querySelector('.job-col-body');
      if (items.length === 0) {
        body.innerHTML = '<div class="job-col-empty">No items</div>';
      } else {
        items.slice(0, 15).forEach(r => body.appendChild(_buildColCard(r)));
      }
      if (col.droppable) {
        body.addEventListener('dragover', (e) => {
          e.preventDefault();
          e.dataTransfer.dropEffect = 'move';
          body.style.outline = '2px solid var(--accent)';
          body.style.borderRadius = '6px';
        });
        body.addEventListener('dragleave', () => { body.style.outline = ''; });
        body.addEventListener('drop', async (e) => {
          e.preventDefault();
          body.style.outline = '';
          const run_id = e.dataTransfer.getData('text/plain');
          if (!run_id) return;
          await fetch(`/api/runs/${run_id}/status`, {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: col.dropStatus }),
          });
          refreshJobBoard();
        });
      }
      frag.appendChild(colEl);
    });
    container.replaceChildren(frag);
  } catch (_) {}
}

function updateJobCardState(run_id, state) {
  setTimeout(refreshJobBoard, state === 'running' ? 0 : 600);
}

async function archiveRun(run_id) {
  if (!run_id) return;
  await fetch(`/api/runs/${run_id}/status`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ status: 'archived' }),
  });
  refreshJobBoard();
  refreshTrashCount();
}

let _trashOpen = false;

async function refreshTrashCount() {
  try {
    const res = await fetch('/api/runs?state=archived&limit=200');
    const runs = await res.json();
    const n = runs.length;
    document.getElementById('trash-count').textContent = n > 0 ? n : '—';
    if (_trashOpen) renderTrash(runs);
  } catch (_) {}
}

function toggleTrash() {
  _trashOpen = !_trashOpen;
  document.getElementById('trash-panel').style.display = _trashOpen ? '' : 'none';
  if (_trashOpen) refreshTrashCount();
}

function renderTrash(runs) {
  const container = document.getElementById('trash-cards');
  const countEl = document.getElementById('trash-panel-count');
  if (!container) return;
  countEl.textContent = `(${runs.length})`;
  if (!runs.length) {
    container.innerHTML = '<span style="font-size:12px;color:var(--text-dim)">Empty.</span>';
    return;
  }
  const frag = document.createDocumentFragment();
  runs.forEach(r => {
    const card = document.createElement('div');
    card.className = 'trash-card';
    card.innerHTML = `
      <div class="trash-card-id">${_esc(_shortId(r.run_id))}</div>
      <div class="trash-card-title">${_esc((r.skill || '?').toUpperCase())}</div>
      <div class="trash-card-meta">${r.when || '—'} · ${r.prev_status || '?'}</div>
      <button class="job-btn" onclick="restoreRun('${r.run_id}')">↩ Restore</button>
    `;
    frag.appendChild(card);
  });
  container.replaceChildren(frag);
}

async function restoreRun(run_id) {
  await fetch(`/api/runs/${run_id}/restore`, { method: 'POST' });
  refreshJobBoard();
  refreshTrashCount();
}

async function openDetailModal(run_id) {
  if (!run_id) return;
  _detailRunId = run_id;
  // Show modal with loading state
  document.getElementById('detail-modal').classList.add('open');
  document.getElementById('detail-skill').textContent = '…';
  document.getElementById('detail-meta').textContent = '';
  document.getElementById('detail-output').textContent = 'Loading…';
  document.getElementById('detail-output').classList.remove('empty');
  document.getElementById('detail-error-section').style.display = 'none';
  document.getElementById('detail-path-section').style.display = 'none';

  try {
    const res = await fetch(`/api/runs/${run_id}`);
    if (!res.ok) throw new Error('not found');
    const r = await res.json();
    const state = r.status || 'unknown';

    document.getElementById('detail-state-badge').innerHTML = _stateBadgeHtml(state);
    document.getElementById('detail-skill').textContent = (r.skill || '?').toUpperCase();

    const started = r.started_at ? new Date(r.started_at).toLocaleString() : '—';
    const dur = r.duration_s != null ? `${r.duration_s}s` : '—';
    document.getElementById('detail-meta').innerHTML =
      `Started: <span>${_esc(started)}</span> &nbsp;·&nbsp; Duration: <span>${_esc(dur)}</span> &nbsp;·&nbsp; ID: <span style="font-family:monospace;font-size:10px">${_esc(run_id)}</span>`;

    const prompt = (r.prompt || '').trim();
    const promptEl = document.getElementById('detail-prompt');
    promptEl.textContent = prompt || '—';
    promptEl.classList.toggle('empty', !prompt);

    const output = (r.output || '').trim();
    const outputEl = document.getElementById('detail-output');
    outputEl.textContent = output || '(no output)';
    outputEl.classList.toggle('empty', !output);

    const error = (r.error || '').trim();
    if (error) {
      document.getElementById('detail-error').textContent = error;
      document.getElementById('detail-error-section').style.display = '';
    }

    const path = (r.output_path || '').trim();
    if (path) {
      document.getElementById('detail-path').textContent = path;
      document.getElementById('detail-path-section').style.display = '';
    }

    const canRetry = state !== 'running' && state !== 'sent';
    document.getElementById('detail-retry-btn').style.display = canRetry ? '' : 'none';
  } catch (err) {
    document.getElementById('detail-output').textContent = `Error loading run: ${err}`;
  }
}

function closeDetailModal() {
  document.getElementById('detail-modal').classList.remove('open');
  _detailRunId = null;
}

async function retryRun(run_id) {
  if (!run_id) return;
  try {
    const res = await fetch(`/api/runs/${run_id}/retry`, { method: 'POST' });
    const data = await res.json();
    if (!data.ok) { alert('Retry failed: ' + (data.error || 'unknown')); return; }
    const command = selectedAgent === 'codex' ? `$${data.skill} ` : `/${data.skill} `;
    socket.emit('skill_selected', { skill: data.skill, phrase: command });
    injectCommand(command + (data.prompt || ''));
    closeDetailModal();
  } catch (err) {
    alert('Retry error: ' + err);
  }
}

function retryFromDetail() {
  if (_detailRunId) retryRun(_detailRunId);
}

// Close detail modal on backdrop click
document.getElementById('detail-modal').addEventListener('click', function(e) {
  if (e.target === this) closeDetailModal();
});

// Initial load + polling
refreshJobBoard();
refreshTrashCount();
updateWindows(selectedAgent);
initPaceMarkers();
