    const winMin   = parseFloat(marker.dataset.windowMinutes);
    const wrap     = marker.closest('.win-bar-wrap');
    const bar      = wrap ? wrap.querySelector('.win-bar') : null;
    const usedPct  = bar ? parseFloat(bar.style.width) || 0 : 0;
    _applyPaceMarker(marker, _pacePct(resetsAt, winMin), usedPct);
  });
}, 60000);
