}

function _latestLinearRuns(items) {
  const unlinked = [];
  const byIssue = new Map();
  items.forEach(run => {
    const issueId = run.linear_issue_id;
    if (!issueId) {
      unlinked.push(run);
      return;
    }
    const current = byIssue.get(issueId);
    if (!current || _preferRun(run, current)) byIssue.set(issueId, run);
  });
  return unlinked.concat(Array.from(byIssue.values()));
}

// run_progress state: run_id -> {snippet, turn}
const _runProgress = {};

function _buildColCard(run) {
  const state = run._boardStatus || run.status || run.state || 'unknown';
  const card = document.createElement('div');
  card.className = 'job-card';
  card.dataset.runId = run.run_id || '';
  const prompt = (run.prompt || '').trim();
  const when = run.when || '';
  const dur = run.duration || '';
  const latestRunStatus = run.latest_run_status || run.status || '';
  const isRunning = latestRunStatus === 'running';
  const canRetry = !isRunning && !!run.latest_run_id;
  const isDraggable = false;
  const attempt = run.attempt || 0;
  const startedAt = run.started_at || '';
  const progress = _runProgress[run.latest_run_id || run.run_id] || {};

  const elapsedHtml = isRunning && startedAt
    ? `<span class="job-card-elapsed" data-started="${_esc(startedAt)}" data-run-id="${_esc(run.latest_run_id || run.run_id)}">0s</span>`
    : '';
  const turnHtml = isRunning && progress.turn ? `<span class="job-card-turn"> · T:${progress.turn}</span>` : '';
  const statusLineHtml = isRunning && progress.snippet
    ? `<div class="job-card-status-line">${_esc(progress.snippet)}</div>` : '';
  const attemptHtml = attempt > 0 ? `<span class="job-card-attempt">↺${attempt}</span> ` : '';
  const tokensHtml = (run.input_tokens || run.output_tokens)
    ? `<span style="font-size:10px;color:var(--text-dim)">${_fmt((run.input_tokens||0)+(run.output_tokens||0))} tok</span>` : '';
  const modelLabel = run.model || run.agent || '';
  const modelBadge = modelLabel ? ` <span class="model-badge">${_esc(modelLabel)}</span>` : '';
  const pa = run.preferred_agent || '';
  const paLabel = pa === 'claude' ? 'CLAUDE' : pa === 'codex' ? 'CODEX' : '·';
  const paClass = pa || 'none';
  const agentLocked = isRunning || state === 'in_progress';
  const agentBadge = run._is_linear_issue
    ? ` <span class="agent-badge ${_esc(paClass)}${agentLocked ? ' locked' : ''}" title="${agentLocked ? 'Agent locked while in progress' : 'Click to toggle agent'}" ${agentLocked ? '' : `onclick="event.stopPropagation();setIssueAgent('${_esc(run.linear_issue_id)}','${_esc(pa)}')"`}>${_esc(paLabel)}</span>`
    : '';
  const issueLabel = run.skill || run.identifier || '?';
  const issueTitle = run.title || prompt || '';

  card.innerHTML = `
    <div class="job-card-id">${attemptHtml}${_esc(issueLabel)}${modelBadge}${agentBadge}</div>
    <div class="job-card-title">${_esc(issueTitle)}</div>
    ${prompt ? `<div class="job-card-prompt">${_esc(prompt)}</div>` : ''}
    ${statusLineHtml}
    <div class="job-card-footer">
      <span>${isRunning ? elapsedHtml + turnHtml : (when ? 'Updated ' + _esc(when) : '—')}</span>
      <span class="job-card-dur">${tokensHtml || _esc(dur)}</span>
    </div>
  `;
  if (isRunning) {
    const cancelBtn = document.createElement('button');
    cancelBtn.className = 'cancel-btn';
    cancelBtn.textContent = '✕ Cancel';
    cancelBtn.onclick = (e) => { e.stopPropagation(); cancelRun(run.run_id); };
    card.appendChild(cancelBtn);
  }
  if (run.linear_issue_id && state !== 'cancelled') {
    const dismissBtn = document.createElement('button');
    dismissBtn.className = 'job-card-dismiss';
    dismissBtn.textContent = '✕';
    dismissBtn.title = 'Cancel issue';
    dismissBtn.onclick = (e) => { e.stopPropagation(); cancelLinearIssueById(run.linear_issue_id); };
    card.appendChild(dismissBtn);
  }
  if (canRetry) {
    const group = document.createElement('div');
    group.className = 'job-btn-group';
    const btnC = document.createElement('button');
    btnC.className = 'job-btn retry-claude';
    btnC.textContent = '↺ Claude';
    btnC.title = 'Continue with Claude';
    btnC.onclick = (e) => { e.stopPropagation(); retryRun(run.run_id, 'claude'); };
    const btnX = document.createElement('button');
    btnX.className = 'job-btn retry-codex';
    btnX.textContent = '↺ Codex';
    btnX.title = 'Continue with Codex';
    btnX.onclick = (e) => { e.stopPropagation(); retryRun(run.run_id, 'codex'); };
    group.appendChild(btnC);
    group.appendChild(btnX);
    card.appendChild(group);
  }
  card.addEventListener('click', (e) => {
    if (e.target.classList.contains('job-btn') || e.target.classList.contains('cancel-btn')) return;
    openDetailModal(run.run_id);
  });
  return card;
}

async function cancelRun(run_id) {
  if (!run_id) return;
  try {
    await fetch(`/api/runs/${run_id}`, { method: 'DELETE' });
    delete _runProgress[run_id];
    refreshJobBoard();
  } catch (err) {
    console.error('Cancel failed:', err);
  }
}

async function setIssueAgent(issueId, currentAgent) {
  if (!issueId) return;
  const next = currentAgent === 'claude' ? 'codex' : 'claude';
  try {
    await fetch(`/api/linear/issues/${issueId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ preferred_agent: next }),
    });
    refreshJobBoard();
  } catch (err) {
    console.error('setIssueAgent failed:', err);
  }
}

function _tickElapsedTimers() {
  document.querySelectorAll('[data-started][data-run-id]').forEach(el => {
    const started = new Date(el.dataset.started);
    if (isNaN(started)) return;
    const elapsed = Math.floor((Date.now() - started) / 1000);
    if (elapsed < 60) el.textContent = elapsed + 's';
    else if (elapsed < 3600) el.textContent = Math.floor(elapsed/60) + 'm ' + (elapsed%60) + 's';
    else el.textContent = Math.floor(elapsed/3600) + 'h ' + Math.floor((elapsed%3600)/60) + 'm';
  });
}
setInterval(_tickElapsedTimers, 1000);

let _linearConfigured = false;

async function refreshJobBoard() {
  try {
    const fetches = [fetch('/api/runs?state=running'), fetch('/api/runs?limit=80')];
    if (_linearConfigured) fetches.push(fetch('/api/linear/issues'));
    const results = await Promise.all(fetches);
    const running = await results[0].json();
    const recent = await results[1].json();
    const linearIssues = _linearConfigured && results[2] ? await results[2].json() : [];

    const latestRuns = _latestLinearRuns([
      ...running.map(r => ({ ...r, status: 'running' })),
      ...recent.filter(r => r.linear_issue_id),
    ]);
    const latestRunByIssue = new Map();
    latestRuns.forEach(run => {
      if (run.linear_issue_id) latestRunByIssue.set(run.linear_issue_id, run);
    });

    let all = linearIssues.map(issue => {
      const latest = latestRunByIssue.get(issue.id);
      const boardStatus = _linearStateToBoard(issue.state);
      return {
        run_id: latest?.run_id || ('linear-' + issue.id),
        latest_run_id: latest?.run_id || '',
        latest_run_status: latest?.status || '',
        linear_issue_id: issue.id,
        linear_url: issue.url,
        identifier: issue.identifier,
        skill: issue.identifier,
        title: issue.title,
        prompt: issue.title,
        status: boardStatus,
        _boardStatus: boardStatus,
        started_at: latest?.started_at || issue.created_at,
        when: latest?.when || '',
        duration: latest?.duration || '',
        attempt: latest?.attempt || 0,
        model: latest?.model || latest?.agent || '',
        agent: latest?.agent || '',
        preferred_agent: issue.preferred_agent || '',
        input_tokens: latest?.input_tokens || 0,
        output_tokens: latest?.output_tokens || 0,
        _is_linear_issue: true,
      };
    });

    _boardItemsByRunId = {};
    all.forEach(item => { _boardItemsByRunId[item.run_id] = item; });

    const byCol = {};
    ALL_COLS.forEach(c => { byCol[c.key] = []; });
    all.forEach(r => {
      const state = r._boardStatus || r.status || r.state || 'unknown';
      const col = ALL_COLS.find(c => c.states.includes(state));
      if (col) byCol[col.key].push(r);
    });
    _cancelledItems = all.filter(r => (r._boardStatus || r.status || r.state || 'unknown') === 'cancelled');

    const container = document.getElementById('job-board-cols');
    if (!container) return;

    const runningCount = byCol['in_progress']?.length || 0;
    document.getElementById('job-board-meta').textContent =
      runningCount > 0 ? `${runningCount} in progress · ${all.length} total tasks` : `${all.length} total tasks`;

    const frag = document.createDocumentFragment();
    JOB_COLS.forEach(col => frag.appendChild(_buildCol(col, byCol[col.key] || [])));
    container.replaceChildren(frag);

    const cancelledChip = document.getElementById('cancelled-count-chip');
    const trashCount = document.getElementById('trash-count');
    if (trashCount) trashCount.textContent = String(_cancelledItems.length);
    if (cancelledChip) cancelledChip.classList.toggle('open', _trashOpen);
    if (_trashOpen) renderTrash(_cancelledItems);
  } catch (_) {}
}

function updateJobCardState(run_id, state) {
  setTimeout(refreshJobBoard, state === 'running' ? 0 : 600);
}

