let _colLimit = 15;
let _boardItemsByRunId = {};
let _trashOpen = false;
let _cancelledItems = [];
let _pendingBoardRefresh = false;
let _detailLinearInitial = null;

function _safeLocalStorage() {
  try { return window.localStorage; } catch (_) { return null; }
}

function _storageGet(key, fallback = '') {
  const store = _safeLocalStorage();
  if (!store) return fallback;
  try { return store.getItem(key) ?? fallback; } catch (_) { return fallback; }
}

function _storageSet(key, value) {
  const store = _safeLocalStorage();
  if (!store) return;
  try { store.setItem(key, value); } catch (_) {}
}

function _storageRemove(key) {
  const store = _safeLocalStorage();
  if (!store) return;
  try { store.removeItem(key); } catch (_) {}
}

function _isModalOpen(id) {
  return !!document.getElementById(id)?.classList.contains('open');
}

function _currentLinearDraftKey() {
  return _detailLinearIssueId ? `agenticos.draft.linear.${_detailLinearIssueId}` : '';
}

function _saveDraft(key, value) {
  if (!key) return;
  _storageSet(key, value);
}

function _loadDraft(key, fallback = '') {
  return key ? _storageGet(key, fallback) : fallback;
}

function _clearDraft(key) {
  if (!key) return;
  _storageRemove(key);
}

function _getDetailReplyValue() {
  return document.getElementById('detail-reply-input')?.value || '';
}

function _setDetailReplyValue(value) {
  const el = document.getElementById('detail-reply-input');
  if (el) el.value = value;
}

function _getNewIssueDraft() {
  return {
    title: document.getElementById('new-issue-title')?.value || '',
    description: document.getElementById('new-issue-desc')?.value || '',
  };
}

function _saveNewIssueDraft() {
  const draft = _getNewIssueDraft();
  _saveDraft('agenticos.draft.new_issue.title', draft.title);
  _saveDraft('agenticos.draft.new_issue.description', draft.description);
}

function _restoreNewIssueDraft() {
  const titleEl = document.getElementById('new-issue-title');
  const descEl = document.getElementById('new-issue-desc');
  if (titleEl) titleEl.value = _loadDraft('agenticos.draft.new_issue.title');
  if (descEl) descEl.value = _loadDraft('agenticos.draft.new_issue.description');
}

function _clearNewIssueDraft() {
  _clearDraft('agenticos.draft.new_issue.title');
  _clearDraft('agenticos.draft.new_issue.description');
}

function _saveReplyDraft() {
  _saveDraft('agenticos.draft.detail_reply', _getDetailReplyValue());
}

function _restoreReplyDraft() {
  _setDetailReplyValue(_loadDraft('agenticos.draft.detail_reply'));
}

function _clearReplyDraft() {
  _clearDraft('agenticos.draft.detail_reply');
}

function _saveLinearDraft() {
  const key = _currentLinearDraftKey();
  if (!key) return;
  const payload = {
    title: document.getElementById('linear-edit-title')?.value || '',
    description: document.getElementById('linear-edit-desc')?.value || '',
    state: document.getElementById('linear-edit-state')?.value || '',
    preferred_agent: _detailPreferredAgent || 'claude',
  };
  _saveDraft(key, JSON.stringify(payload));
}

function _restoreLinearDraft(issue) {
  const key = _currentLinearDraftKey();
  const fallback = {
    title: issue.title || '',
    description: issue.description || '',
    state: issue.state || '',
    preferred_agent: issue.preferred_agent || 'claude',
  };
  let draft = fallback;
  const raw = _loadDraft(key);
  if (raw) {
    try { draft = { ...fallback, ...JSON.parse(raw) }; } catch (_) {}
  }
  document.getElementById('linear-edit-title').value = draft.title;
  document.getElementById('linear-edit-desc').value = draft.description;
  setDetailIssueAgent(draft.preferred_agent || 'claude');
  return draft;
}

function _clearLinearDraft(issueId = _detailLinearIssueId) {
  if (!issueId) return;
  _clearDraft(`agenticos.draft.linear.${issueId}`);
}

function _detailLinearDirty() {
  if (!_detailLinearInitial || !_detailLinearIssueId || !_isModalOpen('detail-modal')) return false;
  const title = document.getElementById('linear-edit-title')?.value || '';
  const description = document.getElementById('linear-edit-desc')?.value || '';
  const state = document.getElementById('linear-edit-state')?.value || '';
  return title !== (_detailLinearInitial.title || '')
    || description !== (_detailLinearInitial.description || '')
    || state !== (_detailLinearInitial.state || '')
