  }
  try {
    const fetches = [fetch('/api/runs?state=running'), fetch('/api/runs?limit=80')];
    if (_linearConfigured) fetches.push(fetch('/api/linear/issues'));
    const results = await Promise.all(fetches);
    const running = await results[0].json();
    const recent = await results[1].json();
    const linearIssues = _linearConfigured && results[2] ? await results[2].json() : [];

    const latestRuns = _latestLinearRuns([
      ...running.map(r => ({ ...r, status: 'running' })),
      ...recent.filter(r => r.linear_issue_id),
    ]);
    const latestRunByIssue = new Map();
    latestRuns.forEach(run => {
      if (run.linear_issue_id) latestRunByIssue.set(run.linear_issue_id, run);
    });

    let all = linearIssues.map(issue => {
      const latest = latestRunByIssue.get(issue.id);
      const boardStatus = _linearStateToBoard(issue.state);
      return {
        run_id: latest?.run_id || ('linear-' + issue.id),
        latest_run_id: latest?.run_id || '',
        latest_run_status: latest?.status || '',
        linear_issue_id: issue.id,
        linear_url: issue.url,
        identifier: issue.identifier,
        skill: issue.identifier,
        title: issue.title,
        prompt: issue.title,
        status: boardStatus,
        _boardStatus: boardStatus,
        started_at: latest?.started_at || issue.created_at,
        when: latest?.when || '',
        duration: latest?.duration || '',
        attempt: latest?.attempt || 0,
        model: latest?.model || latest?.agent || '',
        agent: latest?.agent || '',
        preferred_agent: issue.preferred_agent || '',
        input_tokens: latest?.input_tokens || 0,
        output_tokens: latest?.output_tokens || 0,
        _is_linear_issue: true,
      };
    });

    _boardItemsByRunId = {};
    all.forEach(item => { _boardItemsByRunId[item.run_id] = item; });

    const byCol = {};
    ALL_COLS.forEach(c => { byCol[c.key] = []; });
    all.forEach(r => {
      const state = r._boardStatus || r.status || r.state || 'unknown';
      const col = ALL_COLS.find(c => c.states.includes(state));
      if (col) byCol[col.key].push(r);
    });
    _cancelledItems = all.filter(r => (r._boardStatus || r.status || r.state || 'unknown') === 'cancelled');

    const container = document.getElementById('job-board-cols');
    if (!container) return;

    const runningCount = byCol['in_progress']?.length || 0;
    document.getElementById('job-board-meta').textContent =
      runningCount > 0 ? `${runningCount} in progress · ${all.length} total tasks` : `${all.length} total tasks`;

    const frag = document.createDocumentFragment();
    JOB_COLS.forEach(col => frag.appendChild(_buildCol(col, byCol[col.key] || [])));
    container.replaceChildren(frag);

    const cancelledChip = document.getElementById('cancelled-count-chip');
    const trashCount = document.getElementById('trash-count');
    if (trashCount) trashCount.textContent = String(_cancelledItems.length);
    if (cancelledChip) cancelledChip.classList.toggle('open', _trashOpen);
    if (_trashOpen) renderTrash(_cancelledItems);
  } catch (_) {}
}

