  const frag = document.createDocumentFragment();
  runs.forEach(r => {
    const card = document.createElement('div');
    card.className = 'trash-card';
    card.innerHTML = `
      <div class="trash-card-id">${_esc(r.identifier || r.skill || _shortId(r.run_id))}</div>
