+    if (!grouped.has(stack)) grouped.set(stack, []);
+    grouped.get(stack).push([name, entry]);
+  });
+  if (!grouped.size) {
+    container.innerHTML = '<div class="job-board-empty">No skills in this registry.</div>';
+    return;
+  }
+  let html = '';
