+  const container = document.getElementById('skill-panel-content');
+  if (!container) return;
+  const grouped = new Map();
+  Object.entries(reg || {}).forEach(([name, entry]) => {
+    const stack = entry.stack || 'uncategorized';
+    if (!grouped.has(stack)) grouped.set(stack, []);
+    grouped.get(stack).push([name, entry]);
+  });
+  if (!grouped.size) {
+    container.innerHTML = '<div class="job-board-empty">No skills in this registry.</div>';
+    return;
+  }
+  let html = '';
+  for (const [stack, skills] of grouped.entries()) {
+    html += `<div class="stack-section"><div class="stack-label">${_esc(stack)}</div><div class="skill-grid">`;
+    for (const [name, entry] of skills) {
+      const trigger = (entry.trigger_phrases && entry.trigger_phrases.length) ? entry.trigger_phrases[0] : name;
+      const risk = entry.security?.risk_level || 'write';
