+      const agents = (entry.agents || ['claude']).join(',');
+      html += `
+        <div class="skill-card ${entry.schedule_eligible ? 'schedulable' : ''}"
+             id="card-${_esc(name)}"
+             data-agents="${_esc(agents)}"
+             data-skill-name="${_esc(name)}"
+             data-skill-trigger="${_esc(trigger)}"
