    document.getElementById('detail-retry-group').style.display = canRetry ? 'inline-flex' : 'none';
    if (canRetry) _updateDetailRetryLock(r.preferred_agent || r.agent || null);

    const isReview = state === 'in_review';
    document.getElementById('detail-approve-btn').style.display = isReview ? '' : 'none';
    document.getElementById('detail-comment-btn').style.display = r.linear_issue_id ? '' : 'none';
    document.getElementById('detail-reply-section').style.display = r.linear_issue_id ? '' : 'none';
    _detailLinearIssueId = r.linear_issue_id || null;
    if (isReview) {
      _restoreReplyDraft();
    } else if (_detailLinearIssueId) {
      _clearReplyDraftForIssue(_detailLinearIssueId);
    }

    // Load Linear issue if linked
    if (_linearConfigured && r.linear_issue_id) {
      _loadLinearIssueIntoModal(r.linear_issue_id, boardItem);
    }

    // Fetch previous attempts for this Linear issue or retry chain.
    if (r.linear_issue_id || r.parent_run_id || r.attempt > 0) {
      try {
        const histRes = await fetch(`/api/runs/${run_id}/history`);
        if (histRes.ok) {
          const history = await histRes.json();
          if (requestSeq !== _detailModalLoadSeq || _detailRunId !== run_id || !_isModalOpen('detail-modal')) return;
