async function retryRun(run_id, agent = 'claude', reply = '', attachments = []) {
  if (!run_id) return;
  const boardItem = _boardItemsByRunId[run_id] || null;
  const targetRunId = boardItem?.latest_run_id || run_id;
  if (targetRunId.startsWith('linear-')) { alert('No previous run to continue yet. Move the issue to In Progress first.'); return; }
  try {
    const body = JSON.stringify({ agent, reply, attachments });
    const res = await fetch(`/api/runs/${targetRunId}/retry`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
    });
    const data = await res.json();
    if (!data.ok) { alert('Retry failed: ' + (data.error || 'unknown')); return; }
    closeDetailModal();
    refreshJobBoard();
  } catch (err) {
    alert('Retry error: ' + err);
  }
}

function retryFromDetail(agent = 'claude') {
