    refreshJobBoard();
  } catch (err) { alert('Approve error: ' + err); }
}

async function commentToLinear() {
  const linearIssueId = _detailLinearIssueId || _boardItemsByRunId[_detailRunId]?.linear_issue_id;
  if (!linearIssueId) return;
  const feedback = (document.getElementById('detail-reply-input')?.value || '').trim();
  if (!feedback && !_replyAttachments.length) return;
  try {
    const res = await fetch(`/api/linear/issues/${linearIssueId}/comment`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: 'Human Feedback',
        feedback,
        attachments: _replyAttachments,
      }),
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'comment failed');
    _setDetailReplyValue('');
