async function retryRun(run_id, agent = 'claude', reply = '', attachments = []) {
  if (!run_id) return;
  const boardItem = _boardItemsByRunId[run_id] || null;
  const targetRunId = boardItem?.latest_run_id || run_id;
  if (targetRunId.startsWith('linear-')) { alert('No previous run to continue yet. Move the issue to In Progress first.'); return; }
  try {
    const body = JSON.stringify({ agent, reply, attachments });
    const res = await fetch(`/api/runs/${targetRunId}/retry`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body,
    });
    const data = await res.json();
    if (!data.ok) { alert('Retry failed: ' + (data.error || 'unknown')); return; }
    closeDetailModal();
    refreshJobBoard();
  } catch (err) {
    alert('Retry error: ' + err);
  }
}

function retryFromDetail(agent = 'claude') {
  if (!_detailRunId) return;
  const reply = (document.getElementById('detail-reply-input')?.value || '').trim();
  retryRun(_detailRunId, agent, reply, _replyAttachments);
  _replyAttachments = [];
  _renderAttachList('reply-attach-list', _replyAttachments);
}

async function approveRun() {
  if (!_detailRunId) return;
  const boardItem = _boardItemsByRunId[_detailRunId] || null;
  const linearIssueId = boardItem?.linear_issue_id || _detailLinearIssueId;
  try {
    if (!linearIssueId) throw new Error('No linked Linear issue');
    await fetch(`/api/linear/issues/${linearIssueId}`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ state_name: 'Done' }),
    });
    closeDetailModal();
    refreshJobBoard();
  } catch (err) { alert('Approve error: ' + err); }
}

