  const linearIssueId = _detailLinearIssueId || _boardItemsByRunId[_detailRunId]?.linear_issue_id;
  if (!linearIssueId) return;
  const feedback = (document.getElementById('detail-reply-input')?.value || '').trim();
  if (!feedback && !_replyAttachments.length) return;
  try {
    const res = await fetch(`/api/linear/issues/${linearIssueId}/comment`, {
      method: 'POST',
